export const CATEGORY_LIST = ["Electronics","Home & Living","Fashion","Sports & Outdoors","Books & Media","Toys & Games","Beauty & Health","Automotive","Office Supplies","Garden & Patio","Pet Supplies","Groceries","Jewelry","Musical Instruments","Art & Crafts"];

export const PAGE_SIZE = 24;

export function formatCurrency(value) {
  return '$' + value.toFixed(2);
}

export function StarRating({ rating }) {
  const full = Math.floor(rating);
  const half = rating - full >= 0.5;
  const stars = [];
  for (let i = 0; i < 5; i++) {
    if (i < full) stars.push('full');
    else if (i === full && half) stars.push('half');
    else stars.push('empty');
  }
  return (
    <span className="star-rating" aria-label={`Rating ${rating} out of 5`}>
      {stars.map((s, idx) => (
        <span key={idx} className={`star star-${s}`}>
          ★
        </span>
      ))}
    </span>
  );
}

export function ProductCard({ product }) {
  const IconComp = product.icon;
  return (
    <article className="product-card">
      <div className="product-card-icon">
        <IconComp size={32} />
      </div>
      <div className="product-card-body">
        <h3 className="product-card-title">{product.name}</h3>
        <p className="product-card-category">
          {product.category} · {product.color} · {product.material}
        </p>
        <p className="product-card-desc">{product.description}</p>
        <div className="product-card-tags">
          {product.tags.map((t) => (
            <span key={t} className="tag-chip">
              {t}
            </span>
          ))}
        </div>
        <div className="product-card-footer">
          <StarRating rating={product.rating} />
          <span className="product-card-price">{formatCurrency(product.price)}</span>
        </div>
        <div className="product-card-meta">
          <span>{product.sku}</span>
          <span>Model {product.modelNo} · {product.releaseYear}</span>
          <span>{product.stock > 0 ? `${product.stock} in stock` : 'Out of stock'}</span>
        </div>
      </div>
    </article>
  );
}

export function Sidebar({ activeCategory, onSelectCategory, activeTag, onSelectTag, tags }) {
  return (
    <aside className="dashboard-sidebar">
      <h2 className="sidebar-heading">Categories</h2>
      <ul className="sidebar-list">
        <li>
          <button
            className={activeCategory === null ? 'sidebar-btn active' : 'sidebar-btn'}
            onClick={() => onSelectCategory(null)}
          >
            All Categories
          </button>
        </li>
        {CATEGORY_LIST.map((cat) => (
          <li key={cat}>
            <button
              className={activeCategory === cat ? 'sidebar-btn active' : 'sidebar-btn'}
              onClick={() => onSelectCategory(cat)}
            >
              {cat}
            </button>
          </li>
        ))}
      </ul>
      <h2 className="sidebar-heading">Popular Tags</h2>
      <div className="sidebar-tags">
        <button
          className={activeTag === null ? 'tag-chip active' : 'tag-chip'}
          onClick={() => onSelectTag(null)}
        >
          all
        </button>
        {tags.map((t) => (
          <button
            key={t}
            className={activeTag === t ? 'tag-chip active' : 'tag-chip'}
            onClick={() => onSelectTag(t)}
          >
            {t}
          </button>
        ))}
      </div>
    </aside>
  );
}

export function StatsPanel({ items }) {
  const stats = useMemo(() => {
    const total = items.length;
    const avgPrice = total ? items.reduce((s, p) => s + p.price, 0) / total : 0;
    const avgRating = total ? items.reduce((s, p) => s + p.rating, 0) / total : 0;
    const inStock = items.filter((p) => p.stock > 0).length;
    return { total, avgPrice, avgRating, inStock };
  }, [items]);

  return (
    <div className="stats-panel">
      <div className="stat-box">
        <span className="stat-value">{stats.total}</span>
        <span className="stat-label">Results</span>
      </div>
      <div className="stat-box">
        <span className="stat-value">{formatCurrency(stats.avgPrice)}</span>
        <span className="stat-label">Avg. price</span>
      </div>
      <div className="stat-box">
        <span className="stat-value">{stats.avgRating.toFixed(2)}</span>
        <span className="stat-label">Avg. rating</span>
      </div>
      <div className="stat-box">
        <span className="stat-value">{stats.inStock}</span>
        <span className="stat-label">In stock</span>
      </div>
    </div>
  );
}

export function Pagination({ page, pageCount, onChange }) {
  const pages = [];
  const windowSize = 2;
  for (let p = 1; p <= pageCount; p++) {
    if (p === 1 || p === pageCount || (p >= page - windowSize && p <= page + windowSize)) {
      pages.push(p);
    } else if (pages[pages.length - 1] !== '...') {
      pages.push('...');
    }
  }
  return (
    <nav className="pagination" aria-label="Pagination">
      <button disabled={page === 1} onClick={() => onChange(page - 1)}>
        Prev
      </button>
      {pages.map((p, idx) =>
        p === '...' ? (
          <span key={`gap-${idx}`} className="pagination-gap">
            …
          </span>
        ) : (
          <button
            key={p}
            className={p === page ? 'active' : ''}
            onClick={() => onChange(p)}
          >
            {p}
          </button>
        )
      )}
      <button disabled={page === pageCount} onClick={() => onChange(page + 1)}>
        Next
      </button>
    </nav>
  );
}

export default function Dashboard() {
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState(null);
  const [activeTag, setActiveTag] = useState(null);
  const [sortBy, setSortBy] = useState('name-asc');
  const [page, setPage] = useState(1);

  const allTags = useMemo(() => {
    const set = new Set();
    PRODUCTS.forEach((p) => p.tags.forEach((t) => set.add(t)));
    return Array.from(set).sort();
  }, []);

  const filtered = useMemo(() => {
    let list = PRODUCTS;
    if (category) list = list.filter((p) => p.category === category);
    if (activeTag) list = list.filter((p) => p.tags.includes(activeTag));
    if (search.trim()) {
      const q = search.trim().toLowerCase();
      list = list.filter(
        (p) =>
          p.name.toLowerCase().includes(q) ||
          p.description.toLowerCase().includes(q) ||
          p.sku.toLowerCase().includes(q)
      );
    }
    const sorted = [...list];
    switch (sortBy) {
      case 'name-asc':
        sorted.sort((a, b) => a.name.localeCompare(b.name));
        break;
      case 'name-desc':
        sorted.sort((a, b) => b.name.localeCompare(a.name));
        break;
      case 'price-asc':
        sorted.sort((a, b) => a.price - b.price);
        break;
      case 'price-desc':
        sorted.sort((a, b) => b.price - a.price);
        break;
      case 'rating-desc':
        sorted.sort((a, b) => b.rating - a.rating);
        break;
      default:
        break;
    }
    return sorted;
  }, [category, activeTag, search, sortBy]);

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const pageItems = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  const handleSelectCategory = useCallback((cat) => {
    setCategory(cat);
    setPage(1);
  }, []);

  const handleSelectTag = useCallback((t) => {
    setActiveTag(t);
    setPage(1);
  }, []);

  return (
    <div className="dashboard-root">
      <header className="dashboard-header">
        <h1>Product Catalog Dashboard</h1>
        <p className="dashboard-subtitle">
          Browse {PRODUCTS.length.toLocaleString()} products across {CATEGORY_LIST.length} categories.
        </p>
        <div className="dashboard-controls">
          <input
            type="search"
            placeholder="Search products…"
            value={search}
            onChange={(e) => {
              setSearch(e.target.value);
              setPage(1);
            }}
            className="search-input"
          />
          <select
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value)}
            className="sort-select"
          >
            <option value="name-asc">Name (A–Z)</option>
            <option value="name-desc">Name (Z–A)</option>
            <option value="price-asc">Price (Low–High)</option>
            <option value="price-desc">Price (High–Low)</option>
            <option value="rating-desc">Rating (High–Low)</option>
          </select>
        </div>
      </header>

      <StatsPanel items={filtered} />

      <div className="dashboard-layout">
        <Sidebar
          activeCategory={category}
          onSelectCategory={handleSelectCategory}
          activeTag={activeTag}
          onSelectTag={handleSelectTag}
          tags={allTags}
        />
        <main className="dashboard-main">
          <div className="product-grid">
            {pageItems.map((product) => (
              <ProductCard key={product.id} product={product} />
            ))}
          </div>
          {pageItems.length === 0 && (
            <p className="empty-state">No products match your filters.</p>
          )}
          <Pagination page={page} pageCount={pageCount} onChange={setPage} />
        </main>
      </div>
    </div>
  );
}
